class Solution:
    def evaluate(self, expression: str) -> int:
        self.s = expression
        self.i = 0
        return self.parse()
    def parse(self) -> int:
        c = self.s[self.i]
        if c.isdigit() or c == '-':
            j = self.i
            self.i += 1
            while self.i < len(self.s) and self.s[self.i].isdigit():
                self.i += 1
            return int(self.s[j:self.i])
        op = self.s[self.i:self.i + 3]
        self.i += 4
        a = self.parse()
        self.i += 1
        b = self.parse()
        self.i += 1
        if op == 'add': return a + b
        if op == 'sub': return a - b
        if op == 'mul': return a * b
        return a // b

