class Solution {
    private String s; private int i;
    public int evaluate(String expression) {
        s = expression; i = 0;
        return (int) parse();
    }
    private long parse() {
        if (Character.isDigit(s.charAt(i)) || s.charAt(i) == '-') {
            int j = i; i++;
            while (i < s.length() && Character.isDigit(s.charAt(i))) i++;
            return Long.parseLong(s.substring(j, i));
        }
        String op = s.substring(i, i + 3); i += 4;
        long a = parse(); i++;
        long b = parse(); i++;
        switch (op) {
            case "add": return a + b;
            case "sub": return a - b;
            case "mul": return a * b;
            default: return a / b;
        }
    }
}

