class Solution {
public:
    int evaluate(string expression) {
        vector<string> ops;
        vector<vector<long long>> args;
        long long cur = 0; bool has = false;
        int i = 0, n = expression.size();
        while (i < n) {
            char c = expression[i];
            if (isdigit(c) || c == '-') {
                int j = i;
                while (i < n && isdigit(expression[i])) i++;
                cur = stoll(expression.substr(j, i - j)); has = true;
                continue;
            }
            if (c == '(') {
                ops.push_back(expression.substr(i - 3, 3));
                args.push_back({cur}); has = false;
            } else if (c == ',') {
                args.back().push_back(cur); has = false;
            } else if (c == ')') {
                long long a = args.back()[0], b = args.back()[1];
                args.pop_back();
                string op = ops.back(); ops.pop_back();
                if (op == "add") cur = a + b;
                else if (op == "sub") cur = a - b;
                else if (op == "mul") cur = a * b;
                else cur = a / b;
                has = true;
            }
            i++;
        }
        return (int)cur;
    }
};

