class Solution {
    public int evaluate(String expression) {
        Deque<String> ops = new ArrayDeque<>();
        Deque<List<Long>> args = new ArrayDeque<>();
        Long cur = null;
        int i = 0, n = expression.length();
        while (i < n) {
            char c = expression.charAt(i);
            if (Character.isDigit(c) || c == '-') {
                int j = i;
                while (i < n && Character.isDigit(expression.charAt(i))) i++;
                cur = Long.parseLong(expression.substring(j, i));
                continue;
            }
            if (c == '(') {
                ops.push(expression.substring(i - 3, i));
                List<Long> l = new ArrayList<>(); l.add(cur);
                args.push(l); cur = null;
            } else if (c == ',') {
                args.peek().add(cur); cur = null;
            } else if (c == ')') {
                List<Long> ab = args.pop();
                String op = ops.pop();
                long a = ab.get(0), b = ab.get(1);
                if (op.equals("add")) cur = a + b;
                else if (op.equals("sub")) cur = a - b;
                else if (op.equals("mul")) cur = a * b;
                else cur = a / b;
            }
            i++;
        }
        return cur.intValue();
    }
}

