        if (c === '(') {
            ops.push(expression.slice(i - 3, i));
            args.push([cur]);
            cur = null;
        } else if (c === ',') {
            args[args.length - 1].push(cur);
            cur = null;
        } else if (c === ')') {
            const [a, b] = args.pop();
            const op = ops.pop();
            if (op === 'add') cur = a + b;
            else if (op === 'sub') cur = a - b;
            else if (op === 'mul') cur = a * b;
            else cur = Math.trunc(a / b);
        }
        i++
    }
    return cur;
};
